import type { Context, PropsWithChildren, ReactElement } from "react";
import { createContext, useContext } from "react";

export type CreateTranslationContextOptions<TValue> = {
	/**
	 * Supply one to let components render outside the provider; omit it to make
	 * `useTranslationContext()` throw.
	 *
	 * Chat's React SDK supplies one, so its primitives render standalone. Chat's React Native SDK
	 * keeps its own hand-rolled context instead: it throws when the value is *identity-equal to the
	 * default* and `NODE_ENV !== 'test'`, which is a house convention shared by ~10 of its contexts
	 * rather than anything i18n-specific, and is deliberately not modelled here. The no-default
	 * overload is for an SDK with no sensible fallback translator.
	 */
	defaultValue?: TValue;
	/** Names the context in React DevTools and in the missing-provider error. */
	displayName?: string;
};

export type TranslationContextBinding<TValue, TContextValue = TValue | undefined> = {
	TranslationContext: Context<TContextValue>;
	TranslationProvider: (props: PropsWithChildren<{ value: TValue }>) => ReactElement;
	useTranslationContext: () => TValue;
};

/**
 * Builds an SDK's translation context, provider and hook.
 *
 * Overloaded so the context type tracks whether a default exists — with one, reading the raw
 * context never yields `undefined` and consumers need not narrow.
 */
export function createTranslationContext<TValue extends object>(
	options: CreateTranslationContextOptions<TValue> & { defaultValue: TValue },
): TranslationContextBinding<TValue, TValue>;
export function createTranslationContext<TValue extends object>(
	options?: CreateTranslationContextOptions<TValue>,
): TranslationContextBinding<TValue>;
export function createTranslationContext<TValue extends object>({
	defaultValue,
	displayName = "TranslationContext",
}: CreateTranslationContextOptions<TValue> = {}): TranslationContextBinding<TValue> {
	const TranslationContext = createContext<TValue | undefined>(defaultValue);
	TranslationContext.displayName = displayName;

	const TranslationProvider = ({
		children,
		value,
	}: PropsWithChildren<{ value: TValue }>): ReactElement => (
		<TranslationContext.Provider value={value}>{children}</TranslationContext.Provider>
	);

	const useTranslationContext = (): TValue => {
		const value = useContext(TranslationContext);
		if (typeof value === "undefined") {
			throw new Error(
				`${displayName} was read outside of its provider, and no default was configured.`,
			);
		}

		return value;
	};

	return { TranslationContext, TranslationProvider, useTranslationContext };
}
